package com.example.InvestIQ.controller;

import com.example.InvestIQ.service.AlphaVantageService;
import com.example.InvestIQ.service.MarketDataService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/market")
public class MarketDataController {

	private final MarketDataService marketDataService;
	private final AlphaVantageService alphaVantageService;

	public MarketDataController(MarketDataService marketDataService,
								AlphaVantageService alphaVantageService) {
		this.marketDataService = marketDataService;
		this.alphaVantageService = alphaVantageService;
	}

	// ── Existing endpoint (unchanged) ──────────────────────────────────────────
	@GetMapping("/stocks/{symbol}")
	public ResponseEntity<Map<String, Object>> getStockQuote(@PathVariable String symbol) {
        System.out.println("Fetching stock quote for symbol: " + symbol);
		return marketDataService.fetchStockQuote(symbol)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}

	// ── Live current price for any symbol (stock, bond, commodity) ─────────────
	// GET /market/quote/AAPL   or   /market/quote/XAUUSD   or   /market/quote/US10Y
	@GetMapping("/quote/{symbol}")
	public ResponseEntity<Map<String, Object>> getCurrentPrice(@PathVariable String symbol) {
		return alphaVantageService.fetchGlobalQuote(symbol)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}

	// ── Intraday price history (for charts) ────────────────────────────────────
	// GET /market/history/AAPL?interval=5min
	// interval: 1min | 5min | 15min | 30min | 60min  (default: 5min)
	@GetMapping("/history/{symbol}")
	public ResponseEntity<Map<String, Object>> getPriceHistory(
			@PathVariable String symbol,
			@RequestParam(defaultValue = "5min") String interval) {
		return alphaVantageService.fetchPriceHistory(symbol, interval)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}
}

package com.example.InvestIQ.controller;

import com.example.InvestIQ.service.AlphaVantageService;
import com.example.InvestIQ.service.MarketDataService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/market")
public class MarketDataController {

	private final MarketDataService marketDataService;
	private final AlphaVantageService alphaVantageService;

	public MarketDataController(MarketDataService marketDataService,
								AlphaVantageService alphaVantageService) {
		this.marketDataService = marketDataService;
		this.alphaVantageService = alphaVantageService;
	}

	// ── Existing endpoint (unchanged) ──────────────────────────────────────────
	@GetMapping("/stocks/{symbol}")
	public ResponseEntity<Map<String, Object>> getStockQuote(@PathVariable String symbol) {
        System.out.println("Fetching stock quote for symbol: " + symbol);
		return marketDataService.fetchStockQuote(symbol)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}

	// ── Live current price for any symbol (stock, bond, commodity) ─────────────
	// GET /market/quote/AAPL   or   /market/quote/XAUUSD   or   /market/quote/US10Y
	@GetMapping("/quote/{symbol}")
	public ResponseEntity<Map<String, Object>> getCurrentPrice(@PathVariable String symbol) {
		return alphaVantageService.fetchGlobalQuote(symbol)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}

	// ── Intraday price history (for charts) ────────────────────────────────────
	// GET /market/history/AAPL?interval=5min
	// interval: 1min | 5min | 15min | 30min | 60min  (default: 5min)
	@GetMapping("/history/{symbol}")
	public ResponseEntity<Map<String, Object>> getPriceHistory(
			@PathVariable String symbol,
			@RequestParam(name = "interval", required = false, defaultValue = "5min") String interval) {
		System.out.println("getPriceHistory called with symbol: " + symbol + ", interval: " + interval);
		return alphaVantageService.fetchPriceHistory(symbol, interval)
				.map(ResponseEntity::ok)
				.orElse(ResponseEntity.notFound().build());
	}
}

package com.example.InvestIQ.service;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.util.UriComponentsBuilder;

import java.util.Collections;
import java.util.Map;
import java.util.Optional;

@Service
public class AlphaVantageService {

	private final RestTemplate restTemplate;

	@Value("${alpha.vantage.base-url:https://www.alphavantage.co/query}")
	private String baseUrl;

	@Value("${alpha.vantage.api-key:}")
	private String apiKey;

	public AlphaVantageService(RestTemplate restTemplate) {
		this.restTemplate = restTemplate;
	}

	public Optional<Map<String, Object>> fetchCompanyOverview(String symbol) {
		Map<String, Object> response = callApi("OVERVIEW", symbol);
		if (response.isEmpty() || hasApiError(response) || !response.containsKey("Symbol")) {
			return Optional.empty();
		}
		return Optional.of(response);
	}

	public Optional<Map<String, Object>> fetchGlobalQuote(String symbol) {
		Map<String, Object> response = callApi("GLOBAL_QUOTE", symbol);
		if (hasApiError(response)) {
			return Optional.empty();
		}

		Object quoteObject = response.get("Global Quote");
		if (!(quoteObject instanceof Map<?, ?> quoteMap) || quoteMap.isEmpty()) {
			return Optional.empty();
		}

		@SuppressWarnings("unchecked")
		Map<String, Object> quote = (Map<String, Object>) quoteMap;
		return Optional.of(quote);
	}

	/**
	 * Intraday price history for any symbol.
	 * interval: "1min" | "5min" | "15min" | "30min" | "60min"
	 * Returns ~100 data points keyed by timestamp.
	 */
	@SuppressWarnings("unchecked")
	public Optional<Map<String, Object>> fetchPriceHistory(String symbol, String interval) {
		String normalizedSymbol = normalizeSymbol(symbol);
		if (normalizedSymbol == null) {
			return Optional.empty();
		}

		String safeInterval = normalizeInterval(interval);
		String effectiveApiKey = resolveApiKey();
		if (effectiveApiKey == null) {
			return Optional.empty();
		}

		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", "TIME_SERIES_INTRADAY")
				.queryParam("symbol", normalizedSymbol)
				.queryParam("interval", safeInterval)
				.queryParam("outputsize", "compact")
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);
		if (response == null || response.isEmpty()) {
			return Optional.empty();
		}

		// Some Alpha Vantage keys do not include intraday history (premium-only).
		// In that case, fall back to daily history so frontend still gets chart data.
		if (isIntradayPremiumBlocked(response)) {
			Optional<Map<String, Object>> daily = fetchDailyHistory(normalizedSymbol, effectiveApiKey);
			return daily.isPresent() ? daily : Optional.of(response);
		}

		if (hasApiError(response)) {
			return Optional.of(response);
		}

		String timeSeriesKey = "Time Series (" + safeInterval + ")";
		Object timeSeries = response.get(timeSeriesKey);
		if (!(timeSeries instanceof Map<?, ?> tsMap) || tsMap.isEmpty()) {
			return Optional.of(response);
		}

		return Optional.of((Map<String, Object>) tsMap);
	}

	@SuppressWarnings("unchecked")
	private Optional<Map<String, Object>> fetchDailyHistory(String normalizedSymbol, String effectiveApiKey) {
		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", "TIME_SERIES_DAILY")
				.queryParam("symbol", normalizedSymbol)
				.queryParam("outputsize", "compact")
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);
		if (response == null || response.isEmpty() || hasApiError(response)) {
			return Optional.empty();
		}

		Object timeSeries = response.get("Time Series (Daily)");
		if (!(timeSeries instanceof Map<?, ?> tsMap) || tsMap.isEmpty()) {
			return Optional.empty();
		}

		return Optional.of((Map<String, Object>) tsMap);
	}

	private Map<String, Object> callApi(String function, String symbol) {
		String normalizedSymbol = normalizeSymbol(symbol);
		String effectiveApiKey = resolveApiKey();
		if (normalizedSymbol == null || effectiveApiKey == null) {
			return Collections.emptyMap();
		}

		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", function)
				.queryParam("symbol", normalizedSymbol)
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);
		return response != null ? response : Collections.emptyMap();
	}

	private String normalizeSymbol(String symbol) {
		if (symbol == null || symbol.isBlank()) {
			return null;
		}
		return symbol.trim().toUpperCase();
	}

	private String normalizeInterval(String interval) {
		if (interval == null || interval.isBlank()) {
			return "5min";
		}
		String safeInterval = interval.trim().toLowerCase();
		if ("1min".equals(safeInterval)
				|| "5min".equals(safeInterval)
				|| "15min".equals(safeInterval)
				|| "30min".equals(safeInterval)
				|| "60min".equals(safeInterval)) {
			return safeInterval;
		}
		return "5min";
	}

	private String resolveApiKey() {
		if (apiKey == null || apiKey.isBlank() || apiKey.contains("YOUR_ALPHA_VANTAGE_API_KEY")) {
			// Fallback to demo key so /history works immediately for IBM in local testing.
			return "demo";
		}
		return apiKey.trim();
	}

	private boolean hasApiError(Map<String, Object> response) {
		return response.containsKey("Error Message") || response.containsKey("Information") || response.containsKey("Note");
	}

	private boolean isIntradayPremiumBlocked(Map<String, Object> response) {
		Object info = response.get("Information");
		if (info == null) {
			return false;
		}
		String message = info.toString().toLowerCase();
		return message.contains("premium endpoint") || message.contains("subscribe");
	}
}

package com.example.InvestIQ.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.util.UriComponentsBuilder;

import java.util.Collections;
import java.util.Map;
import java.util.Optional;

@Service
public class AlphaVantageService {

	private static final Logger logger = LoggerFactory.getLogger(AlphaVantageService.class);

	private final RestTemplate restTemplate;

	@Value("${alpha.vantage.base-url:https://www.alphavantage.co/query}")
	private String baseUrl;

	@Value("${alpha.vantage.api-key:}")
	private String apiKey;

	public AlphaVantageService(RestTemplate restTemplate) {
		this.restTemplate = restTemplate;
	}

	public Optional<Map<String, Object>> fetchCompanyOverview(String symbol) {
		Map<String, Object> response = callApi("OVERVIEW", symbol);
		if (response.isEmpty() || hasApiError(response) || !response.containsKey("Symbol")) {
			return Optional.empty();
		}
		return Optional.of(response);
	}

	public Optional<Map<String, Object>> fetchGlobalQuote(String symbol) {
		Map<String, Object> response = callApi("GLOBAL_QUOTE", symbol);
		if (hasApiError(response)) {
			return Optional.empty();
		}

		Object quoteObject = response.get("Global Quote");
		if (!(quoteObject instanceof Map<?, ?> quoteMap) || quoteMap.isEmpty()) {
			return Optional.empty();
		}

		@SuppressWarnings("unchecked")
		Map<String, Object> quote = (Map<String, Object>) quoteMap;
		return Optional.of(quote);
	}

	/**
	 * Intraday price history for any symbol.
	 * interval: "1min" | "5min" | "15min" | "30min" | "60min"
	 * Returns ~100 data points keyed by timestamp.
	 */
	@SuppressWarnings("unchecked")
	public Optional<Map<String, Object>> fetchPriceHistory(String symbol, String interval) {
		String normalizedSymbol = normalizeSymbol(symbol);
		if (normalizedSymbol == null) {
			logger.warn("Invalid symbol provided: {}", symbol);
			return Optional.empty();
		}

		String safeInterval = normalizeInterval(interval);
		String effectiveApiKey = resolveApiKey();
		if (effectiveApiKey == null) {
			logger.warn("No API key available");
			return Optional.empty();
		}

		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", "TIME_SERIES_INTRADAY")
				.queryParam("symbol", normalizedSymbol)
				.queryParam("interval", safeInterval)
				.queryParam("outputsize", "compact")
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		logger.info("Fetching intraday price history for symbol: {} with interval: {}", normalizedSymbol, safeInterval);
		logger.debug("Calling API: {}", url.replaceAll("apikey=[^&]*", "apikey=***"));

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);
		if (response == null || response.isEmpty()) {
			logger.warn("Empty response from intraday API for symbol: {}", normalizedSymbol);
			return fetchDailyHistory(normalizedSymbol, effectiveApiKey);
		}

		logger.debug("Intraday API response keys: {}", response.keySet());

		// If intraday is premium-only, throttled, or otherwise unavailable,
		// use daily history (free endpoint) instead of returning error payloads.
		if (isIntradayPremiumBlocked(response) || hasApiError(response)) {
			logger.info("Intraday endpoint blocked or returned error for symbol: {}, falling back to daily", normalizedSymbol);
			logger.debug("API Error/Information: {}", getApiErrorMessage(response));
			return fetchDailyHistory(normalizedSymbol, effectiveApiKey);
		}

		String timeSeriesKey = "Time Series (" + safeInterval + ")";
		Object timeSeries = response.get(timeSeriesKey);
		if (!(timeSeries instanceof Map<?, ?> tsMap) || tsMap.isEmpty()) {
			logger.info("No intraday time series found with key: {}, falling back to daily", timeSeriesKey);
			return fetchDailyHistory(normalizedSymbol, effectiveApiKey);
		}

		logger.info("Successfully fetched {} data points for symbol: {}", tsMap.size(), normalizedSymbol);
		return Optional.of((Map<String, Object>) tsMap);
	}

	@SuppressWarnings("unchecked")
	private Optional<Map<String, Object>> fetchDailyHistory(String normalizedSymbol, String effectiveApiKey) {
		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", "TIME_SERIES_DAILY")
				.queryParam("symbol", normalizedSymbol)
				.queryParam("outputsize", "compact")
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		logger.info("Fetching daily price history for symbol: {}", normalizedSymbol);
		logger.debug("Calling API: {}", url.replaceAll("apikey=[^&]*", "apikey=***"));

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);

		if (response == null || response.isEmpty()) {
			logger.error("Empty response from daily API for symbol: {}", normalizedSymbol);
			return Optional.empty();
		}

		logger.debug("Daily API response keys: {}", response.keySet());
		logger.debug("Full API response: {}", response);

		if (hasApiError(response)) {
			logger.error("API error for symbol: {} - {}", normalizedSymbol, getApiErrorMessage(response));
			return Optional.empty();
		}

		Object timeSeries = response.get("Time Series (Daily)");
		if (!(timeSeries instanceof Map<?, ?> tsMap) || tsMap.isEmpty()) {
			logger.error("No daily time series data found in response for symbol: {}", normalizedSymbol);
			logger.error("Response keys: {}", response.keySet());
			return Optional.empty();
		}

		logger.info("Successfully fetched {} daily data points for symbol: {}", tsMap.size(), normalizedSymbol);
		return Optional.of((Map<String, Object>) tsMap);
	}

	private Map<String, Object> callApi(String function, String symbol) {
		String normalizedSymbol = normalizeSymbol(symbol);
		String effectiveApiKey = resolveApiKey();
		if (normalizedSymbol == null || effectiveApiKey == null) {
			logger.warn("Invalid input for API call - normalized symbol: {}", normalizedSymbol);
			return Collections.emptyMap();
		}

		String url = UriComponentsBuilder.fromHttpUrl(baseUrl)
				.queryParam("function", function)
				.queryParam("symbol", normalizedSymbol)
				.queryParam("apikey", effectiveApiKey)
				.toUriString();

		logger.info("Calling {} API for symbol: {}", function, normalizedSymbol);
		logger.debug("URL: {}", url.replaceAll("apikey=[^&]*", "apikey=***"));

		Map<String, Object> response = restTemplate.getForObject(url, Map.class);
		if (response != null) {
			logger.debug("API response keys: {}", response.keySet());
		}
		return response != null ? response : Collections.emptyMap();
	}

	private String normalizeSymbol(String symbol) {
		if (symbol == null || symbol.isBlank()) {
			return null;
		}
		return symbol.trim().toUpperCase();
	}

	private String normalizeInterval(String interval) {
		if (interval == null || interval.isBlank()) {
			return "5min";
		}
		String safeInterval = interval.trim().toLowerCase();
		if ("1min".equals(safeInterval)
				|| "5min".equals(safeInterval)
				|| "15min".equals(safeInterval)
				|| "30min".equals(safeInterval)
				|| "60min".equals(safeInterval)) {
			return safeInterval;
		}
		return "5min";
	}

	private String resolveApiKey() {
		if (apiKey == null || apiKey.isBlank() || apiKey.contains("YOUR_ALPHA_VANTAGE_API_KEY")) {
			// Fallback to demo key so /history works immediately for IBM in local testing.
			return "demo";
		}
		return apiKey.trim();
	}

	private boolean hasApiError(Map<String, Object> response) {
		return response.containsKey("Error Message") || response.containsKey("Information") || response.containsKey("Note");
	}

	private boolean isIntradayPremiumBlocked(Map<String, Object> response) {
		Object info = response.get("Information");
		if (info == null) {
			return false;
		}
		String message = info.toString().toLowerCase();
		return message.contains("premium endpoint") || message.contains("subscribe");
	}

	private String getApiErrorMessage(Map<String, Object> response) {
		if (response.containsKey("Error Message")) {
			return "Error Message: " + response.get("Error Message");
		}
		if (response.containsKey("Information")) {
			return "Information: " + response.get("Information");
		}
		if (response.containsKey("Note")) {
			return "Note: " + response.get("Note");
		}
		return "Unknown API error";
	}
}
